package com.lavu.musicsyncbackend.room;

/**
 * One chat message. {@code system} messages are join/leave notices generated by the server.
 *
 * @param image id of an uploaded picture (see MediaStore), or null
 * @param reply the message this one answers, or null
 */
public record ChatMessage(long id, String username, String text, long at, boolean system, String image, Reply reply) {

    /** A short copy of the message being answered, so it still reads once the original has scrolled away. */
    public record Reply(long id, String username, String text, boolean image) {}
}
